/// One row of Raven's `commands` of `cg_consolecmds.c`, the `consoleCommand_t` record with the command function as a Swift function value.
/// C storage cannot hold the address of a Swift function, so the table is hand data on `CGameWorld`.
struct ConsoleCommandRow {
    let cmd: String
    let function: () -> Void
}

/// One row of Raven's `cvarTable` of `cg_main.c`, the `cvarTable_t` record with the cvar handle as a key path into `CGameStorage`.
/// A nil key path is Raven's NULL handle, a cvar the module registers and never reads.
struct CvarTableRow {
    let vmCvar: KeyPath<CGameStorage, JKAMP.VmCvar>?
    let cvarName: String
    let defaultString: String
    let cvarFlags: Int32
}

/// The one instance. `vmMain` has no context argument and the engine calls the module from one thread, so this is not isolated.
public nonisolated(unsafe) var world = CGameWorld()

/// The string pool of rule 9, the only source of a runtime `char *`.
var strings: StringPool { world.strings }
